#include <functional>
#include <vector>

std::vector<std::vector<int>> solveNQueens(int n) {
    std::vector<std::vector<int>> solutions;
    std::vector<int> queens;                  // queens[row] = column
    std::vector<bool> cols(n, false);
    std::vector<bool> diag(2 * n - 1, false); // indexed by row - col + n - 1
    std::vector<bool> anti(2 * n - 1, false); // indexed by row + col

    std::function<void(int)> backtrack = [&](int row) {
        if (row == n) {
            solutions.push_back(queens);
            return;
        }

        for (int col = 0; col < n; col++) {
            // O(1) conflict test, no loop over placed queens.
            if (cols[col] || diag[row - col + n - 1] || anti[row + col]) continue;

            queens.push_back(col);            // choose
            cols[col] = diag[row - col + n - 1] = anti[row + col] = true;

            backtrack(row + 1);               // explore

            queens.pop_back();                // un-choose
            cols[col] = diag[row - col + n - 1] = anti[row + col] = false;
        }
    };

    backtrack(0);
    return solutions;
}
